<?php

/**
 * @package ThemePlate
 */

namespace Tests;

use CardanoPHP\Verifier;
use PHPUnit\Framework\TestCase;

class VerifierTest extends TestCase
{
    public function forTestVerify(): array
    {
        // phpcs:disable Generic.Files.LineLength.TooLong
        return [
            [
                '',
                'a4010103272006215820b89526fd6bf4ba737c55ea90670d16a27f8de6cc1982349b3b676705a2f420c6',
                'Augusta Ada King, Countess of Lovelace',
                'stake1uyvfslqkzgrf6syq5r4jg7pqewv8l65phh024lw5r7vk9qgznhyty',
            ],
            [
                '',
                'a401010327200621582062ed9a163e31c41523248928b311800a50cf93b26fc4bf31993e0acc508f6cb0',
                'A test message from JS',
                'addr_test1qzpe72uycanzj8t6ufryj556wwc97v4v7jmk7u0q43hl4fwwwlnurtju4fwgk5ja34zhu434hpykn4y8skcsw2sshygqwfe2qk',
            ],
            [
                '84582aa201276761646472657373581d617863b5c43bdf0a06608abc82f0573a549714ff69166074dcdde393d8a166686173686564f44b48656c6c6f20776f726c645840fc58155f0cee05bc00e7299af1df1f159ac82a46a055786b259657934eff346eec81349d4678ceabc79f213c66a2bdbfd4ea5d9ebdc630bee5ac9cce75cfc001',
                'a4010103272006215820755b017578b701dc9ddd4eaee67015b4ca8baf66293b7b1d204df426c0ceccb9',
                'Hello world',
                'addr1v9ux8dwy800s5pnq327g9uzh8f2fw98ldytxqaxumh3e8kqumfr6d',
            ],
            [
                '',
                'a50101025839017e80b5521b1645d8661bb04f4bcb3dcb6aec0846e951d465daa036b8aa5b76c1216be7a5a17aacff34c624c9b291c7a4a97182f016665913032720062158201969ae339850bbdf2bac44939fd288174acd0f9de15a4028e334db77414f4da3',
                'testing data sign',
                'addr1q9lgpd2jrvtytkrxrwcy7j7t8h9k4mqggm54r4r9m2srdw92tdmvzgttu7j6z74vlu6vvfxfk2gu0f9fwxp0q9nxtyfsdvmqec'
            ],
            [
                '',
                'a50101025839008630098a25bf49e54c50b26f2835427dcbecb9fd88e8f3d6fb6a3f9f6564074356727cd34f9c12d0b113e7a362bd444e442b2a2b58b0fca7032720062158209bb685d1be41a2c0bec4aef31319c303ddcd69fcb93e7b5a0503cbcf6b46d931',
                'Lorem ipsum dolor sit amet consectetur adipisicing elit.',
                'addr_test1qzrrqzv2ykl5ne2v2zex72p4gf7uhm9elkyw3u7kld4rl8m9vsr5x4nj0nf5l8qj6zc38earv275gnjy9v4zkk9sljnsr3ec7g'
            ],
            [
                '',
                'a5010102581de0858cf822c956f933ec4a24a4d5a5dc4b475c04d59e02e11686028e6c0327200621582099041ef1c2eaac465b166d3af71dbaecc2efb7621b00588aa4e8100f12253867',
                'the quick brown fox jumps over the lazy dog',
                'stake_test1uzzce7pze9t0jvlvfgj2f4d9m395whqy6k0q9cgkscpgumqjkh3v6'
            ],
        ];
        // phpcs:enable
    }

    /**
     * @dataProvider forTestVerify
     */
    public function testVerify(string $signature, string $key, string $message, string $address)
    {
        $this->assertTrue(Verifier::verify($signature, $key, $message, $address));
    }
}
